WITH source AS (SELECT base_rows.*,ROW_NUMBER() OVER(PARTITION BY base_rows.mktcode,base_rows.tgtcode ORDER BY base_rows.bizdate DESC) AS seq FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.volume,t.volume_avg_5 FROM `newzl`.`hsj_stock_hq_basic` b JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) AS base_rows), eligible AS (SELECT * FROM source WHERE seq<=10), sequenced AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS all_seq FROM eligible), hits AS (SELECT mktcode,tgtcode,bizdate,all_seq,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS hit_seq FROM sequenced WHERE volume>volume_avg_5), runs AS (SELECT mktcode,tgtcode,all_seq-hit_seq AS grp,COUNT(*) AS n FROM hits GROUP BY mktcode,tgtcode,all_seq-hit_seq), qualified AS (SELECT mktcode,tgtcode FROM runs GROUP BY mktcode,tgtcode HAVING MAX(n)>=3) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode;
